// RÈGLE — langage des autres enfants : il vient de celui de Joseph et Marie, débloqué par étape de vie
// (nourrisson : rien ; bébé : quelques mots simples ; puis de plus en plus). Juliette parle comme ses parents.
// On y ajoute ce que Néo a appris, si Néo est au moins aussi jeune que l'enfant.
const MOTS_BEBE=['maman','papa','non','oui','encore','bébé','eau','dodo','ballon','balle','chat','chien','lait','pain','pomme','fleur','arbre','regarde','là','veux'];
const MOTS_PAR_ETAPE=[0,20,80,300,800,1600,3000,6000,6000];
// Petits mots de liaison (absents de la liste de fréquence) : appris dès « petit enfant ».
const MOTS_LIAISON='je tu il elle on nous vous ils elles le la les l un une des du de d à au aux et ou en y ne n s c j t m qu ce ça cela a as ai va vais vas me te se mon ma mes ton ta tes sa ses avec pour dans par sur sous chez aussi'.split(' ');
for(const qui of ['joseph','marie','juliette'])for(const m of MOTS_LIAISON)familyLexicons[qui].add(m);
const lexiquesParEtape=new Map();
function lexiqueParAge(etape){
  const n=MOTS_PAR_ETAPE[Math.max(0,Math.min(8,etape))];
  if(!lexiquesParEtape.has(n+'|'+(etape>=2))){
    const parents=[...familyLexicons.joseph];
    const ordre=[...MOTS_BEBE,...parents];
    const set=new Set([...new Set(ordre)].slice(0,n));
    if(etape>=2)for(const m of MOTS_LIAISON)set.add(m);
    lexiquesParEtape.set(n+'|'+(etape>=2),set);
  }
  return lexiquesParEtape.get(n+'|'+(etape>=2));
}
function lexiqueEnfant(enfant,ageNeo,motsNeo){
  const base=new Set(lexiqueParAge(enfant.age??0));
  if(ageNeo<=(enfant.age??0))for(const m of motsNeo)base.add(m);
  return base;
}
